"""教学 Screen Object，真实定位需由 Inspector 核实。"""
from appium.webdriver.common.appiumby import AppiumBy

from autotest.mobile.screens import BaseScreen


class ProfileScreen(BaseScreen):
    TAB = (AppiumBy.ACCESSIBILITY_ID, "profile.tab")
    NAME = (AppiumBy.ACCESSIBILITY_ID, "profile.display_name")

    def open(self):
        self.tap(self.TAB)

    def display_name(self):
        return self.text(self.NAME)
